  }

  // Replace host if present in relative URL.
  if (relative_parsed.host.is_valid()) {
    output->Replace(base_parsed.host, base_url, relative_parsed.host,
                    relative_url);
  } else {
    output->Replace(base_parsed.host, base_url, base_parsed.host, base_url);
  }

  // Replace port if present in relative URL.
  if (relative_parsed.port.is_valid()) {
    output->Replace(base_parsed.port, base_url, relative_parsed.port,
                    relative_url);
  } else {
    output->Replace(base_parsed.port, base_url, base_parsed.port, base_url);
  }

