  if (relative_parsed.path.is_valid()) {
    output->Replace(base_parsed.path, base_url, relative_parsed.path,
                    relative_url);
  } else {
    output->Replace(base_parsed.path, base_url, base_parsed.path, base_url);
  }

  // Replace query if present in relative URL.
  if (relative_parsed.query.is_valid()) {
    output->Replace(base_parsed.query, base_url, relative_parsed.query,
                    relative_url, query_converter);
  } else {
    output->Replace(base_parsed.query, base_url, base_parsed.query, base_url,
