bool ResolveRelativeURL(const char* base_url,
                        const url_parse::Parsed& base_parsed,
                        const CHAR* relative_url,
                        const url_parse::Component& relative_component,
                        CharsetConverter* query_converter,
                        CanonOutput* output,
                        url_parse::Parsed* out_parsed) {
  // Create a Parsed structure for the relative URL
  url_parse::Parsed relative_parsed;
  url_parse::ParseURL(relative_url, relative_component, &relative_parsed);

  // Create replacement mapping
  url_parse::Component replacements[url_parse::Component::MAX_COMPONENTS];
  for (int i = 0; i < url_parse::Component::MAX_COMPONENTS; ++i) {
    replacements[i] = url_parse::Component::Empty();
  }

  // Replace components if present in the relative URL
  if (relative_parsed.scheme.is_valid())
    replacements[url_parse::Component::SCHEME] = relative_parsed.scheme;
  if (relative_parsed.username.is_valid())
    replacements[url_parse::Component::USERNAME] = relative_parsed.username;
  if (relative_parsed.password.is_valid())
    replacements[url_parse::Component::PASSWORD] = relative_parsed.password;
  if (relative_parsed.host.is_valid())
    replacements[url_parse::Component::HOST] = relative_parsed.host;
  if (relative_parsed.port.is_valid())
    replacements[url_parse::Component::PORT] = relative_parsed.port;
  if (relative_parsed.path.is_valid())
    replacements[url_parse::Component::PATH] = relative_parsed.path;
  if (relative_parsed.query.is_valid())
    replacements[url_parse::Component::QUERY] = relative_parsed.query;
  if (relative_parsed.ref.is_valid())
    replacements[url_parse::Component::REF] = relative_parsed.ref;

  // Perform the URL resolution by combining base and relative components
  bool success = url_parse::ResolveRelative(base_url, base_parsed, replacements, output, out_parsed);

  return success;
}

